// Parse actual driver Config and actual immutable byte maps. No DUT substituted or executed.
#define HOST_DRIVER_CONFIG_ONLY
#include "host_axi_driver_non_dpi.cpp"
int main(int argc,char** argv){try{need(argc==2,"V2 input manifest only");Config cfg(argv[1]);stimulus::ReadOnly ro;std::vector<stimulus::ViewAllocation> allocations;stimulus::SparseWrites rw(1024);for(const auto& a:cfg.allocations){if(a.access=="ro")allocations.push_back({a.name,a.address,a.bytes});else if(a.access=="rw")rw.addRange(a.address,a.bytes);}stimulus::loadViews(cfg.viewManifest,allocations,ro);size_t bytes=0;for(const auto& a:allocations){for(uint64_t i=0;i<std::min<uint64_t>(64,a.bytes);++i){(void)ro.byte(a.base+i);(void)ro.byte(a.base+a.bytes-1-i);bytes+=2;}}std::cout<<"PASS_DRIVER_CONFIG_AND_EDGE_BYTES_ONLY profile="<<cfg.profile<<" allocations="<<cfg.allocations.size()<<" edge_bytes="<<bytes<<" DUT_NOT_EXECUTED\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
